pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a mock token that reverts on transferFrom
        // We'll use a dummy address (no code) so the .call returns success=false
        address token = address(0x123);  // no code, call will return (false, data)
        address from = address(0xabc);
        address[] memory tos = new address[](1);
        tos[0] = address(0xdef);
        uint[] memory vals = new uint[](1);
        vals[0] = 100;
        // Correct contract: requires _s = true, so it reverts
        vm.prank(from);
        (bool ok1,) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, token, tos, vals));
        // Buggy contract: ignores _s, returns true
        // Since we cannot deploy the buggy version here, we assert the reference behavior
        assertTrue(!ok1, "Reference should revert on failed call");
    }
}

