pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use a token address that does not implement transferFrom (e.g., zero address)
        address from = address(0x1234);
        address caddress = address(0); // no code, call will revert
        address[] memory tos = new address[](1);
        tos[0] = address(0x5678);
        uint[] memory v = new uint[](1);
        v[0] = 100;

        bool ok;
        try c.transfer(from, caddress, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference reverts (ok == false), buggy returns true (ok == true)
        // Assert the reference behavior: revert
        assertTrue(!ok, "Reference should revert on failed call");
    }
}

