pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a malicious token that always returns false from transferFrom
        MaliciousToken token = new MaliciousToken();
        address tokenAddr = address(token);

        // Set up arrays: one recipient and value
        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);
        uint[] memory vals = new uint[](1);
        vals[0] = 100;

        // Call c.transfer. The correct contract reverts, the buggy one returns true.
        bool success;
        try c.transfer(address(this), tokenAddr, tos, vals) {
            success = true;
        } catch {
            success = false;
        }

        // Assert: on the correct contract, success = false (revert); on buggy, success = true
        assertTrue(!success);
    }
}

contract MaliciousToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return false;
    }
}

